await Promise.all(['Regular','Medium','Bold'].map(style=>figma.loadFontAsync({family:'Noto Sans SC',style})));
await figma.loadFontAsync({family:'SF Pro',style:'Bold'});
const created=[],mutated=[],flows=[];
const urlRx=url=>[{trigger:{type:'ON_CLICK'},actions:[{type:'URL',url,openInNewTab:true}]}];
async function wire(root){const setup=root.findOne(n=>n.name==='Install / scroll target');const scroll=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',navigation:'SCROLL_TO',destinationId:setup.id,transition:{type:'SCROLL_ANIMATE',duration:.4,easing:{type:'EASE_OUT'}}}]}];const nodes=root.findAll(n=>n.type==='INSTANCE'||n.type==='TEXT');for(const n of nodes){let reactions=null;if(n.name==='Action / Secondary'||(n.type==='TEXT'&&n.characters==='快速开始'))reactions=scroll;else if(n.name==='Action / Primary'||(n.type==='TEXT'&&n.characters==='下载 App'))reactions=urlRx('https://apps.apple.com/cn/app/runbuoy/id6795591930');else if(n.name==='Action / 用于对话')reactions=urlRx('https://www.runbuoy.cloud/guide/agent-skill#chatgpt');else if(n.type==='TEXT'){if(n.characters==='使用文档')reactions=urlRx('https://www.runbuoy.cloud/docs/');if(n.characters==='了解隐私 →'||n.characters==='支持  ·  隐私')reactions=urlRx('https://www.runbuoy.cloud/privacy');if(n.characters==='了解任务与进度 →')reactions=urlRx('https://www.runbuoy.cloud/guide/progress');if(n.characters==='了解 Agent 集成 →')reactions=urlRx('https://www.runbuoy.cloud/guide/agent-skill');}if(reactions){await n.setReactionsAsync(reactions);mutated.push(n.id);}}return setup.id;}
for(const [id,mobile] of [['6:70',false],['6:198',true]]){const source=await figma.getNodeByIdAsync(id);await wire(source);const viewport=figma.createFrame();viewport.name=mobile?'▶ 手机交互原型 · 390 × 844':'▶ 桌面交互原型 · 1440 × 960';viewport.resize(mobile?390:1440,mobile?844:960);viewport.x=mobile?1800:160;viewport.y=5100;viewport.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}];viewport.clipsContent=true;viewport.overflowDirection='VERTICAL';figma.currentPage.appendChild(viewport);const clone=source.clone();clone.name='Scrollable homepage';viewport.appendChild(clone);clone.x=clone.y=0;const setup=await wire(clone);created.push(viewport.id,clone.id,...clone.findAll(()=>true).map(n=>n.id));flows.push({nodeId:viewport.id,name:mobile?'手机 · 安装引导':'桌面 · 安装引导',contentId:clone.id,setupId:setup});}
figma.currentPage.flowStartingPoints=flows.map(({nodeId,name})=>({nodeId,name}));
const roots=[];for(const id of ['6:70','6:198']){const n=await figma.getNodeByIdAsync(id);const nodes=n.findAll(()=>true),types={},images=[],fonts={},oversized=[];for(const d of nodes){types[d.type]=(types[d.type]||0)+1;if(d.type==='TEXT'){for(const seg of d.getStyledTextSegments(['fontName'])){const k=seg.fontName.family;fonts[k]=(fonts[k]||0)+1;}if(d.width>n.width)oversized.push({id:d.id,text:d.characters.slice(0,30),width:d.width});}if('fills' in d&&Array.isArray(d.fills)&&d.fills.some(p=>p.type==='IMAGE'))images.push({id:d.id,name:d.name,type:d.type,width:d.width,height:d.height});}roots.push({id:n.id,name:n.name,width:n.width,height:n.height,descendants:nodes.length,types,images,fonts,oversizedText:oversized});}
return {createdNodeIds:created,mutatedNodeIds:mutated,flows,validation:roots};
